files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --border: #0f3460;
  --focus: #f5c542;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.game-card {
  background: var(--card);
  border: 4px solid var(--border);
  border-radius: 12px;
  padding: 24px;
  width: 100%;
  max-width: 480px;
  display: flex;
  flex-direction: column;
  gap: 24px;
  box-shadow: 0 8px 0 rgba(0, 0, 0, 0.3);
}

h1 {
  font-size: 1.5rem;
  text-align: center;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--accent);
}

.scoreboard {
  display: flex;
  justify-content: space-around;
  background: var(--bg);
  border: 3px solid var(--border);
  border-radius: 8px;
  padding: 16px 8px;
}

.score {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.score-label {
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--muted);
}

.score-value {
  font-size: 2rem;
  font-weight: 700;
  color: var(--text);
  font-variant-numeric: tabular-nums;
}

.choices {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

.choice-btn {
  flex: 1 1 0;
  min-width: 90px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 16px 8px;
  background: var(--bg);
  border: 3px solid var(--border);
  border-radius: 8px;
  color: var(--text);
  font-family: inherit;
  font-size: 1rem;
  cursor: pointer;
  transition: transform 0.1s, border-color 0.15s, background 0.15s;
}

.choice-btn:hover {
  border-color: var(--accent);
  background: #1f2a4a;
}

.choice-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.choice-btn:active {
  transform: translateY(2px);
  background: var(--accent);
}

.pixel-icon {
  font-size: 2rem;
  line-height: 1;
  image-rendering: pixelated;
}

.choice-label {
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.round-result {
  text-align: center;
  min-height: 64px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.round-display {
  font-size: 1.1rem;
  color: var(--muted);
}

.result-text {
  font-size: 1.25rem;
  font-weight: 700;
  min-height: 1.5em;
}

.result-text.win { color: #4ade80; }
.result-text.lose { color: var(--accent); }
.result-text.draw { color: var(--focus); }

.reset-btn {
  align-self: center;
  padding: 12px 32px;
  background: transparent;
  border: 3px solid var(--accent);
  border-radius: 8px;
  color: var(--accent);
  font-family: inherit;
  font-size: 1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  cursor: pointer;
  transition: transform 0.1s, background 0.15s, color 0.15s;
}

.reset-btn:hover {
  background: var(--accent);
  color: var(--text);
}

.reset-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.reset-btn:active {
  transform: translateY(2px);
}

@media (max-width: 400px) {
  .game-card { padding: 16px; gap: 16px; }
  h1 { font-size: 1.25rem; }
  .choice-btn { min-width: 0; padding: 12px 4px; }
  .pixel-icon { font-size: 1.6rem; }
  .score-value { font-size: 1.6rem; }
}

const choices = ['rock', 'paper', 'scissors'];
const icons = { rock: '✊', paper: '✋', scissors: '✌️' };

const playerScoreEl = document.getElementById('player-score');
const computerScoreEl = document.getElementById('computer-score');
const roundDisplay = document.getElementById('round-display');
const resultText = document.getElementById('result-text');
const resetBtn = document.getElementById('reset-btn');
const choiceButtons = document.querySelectorAll('.choice-btn');

let playerScore = 0;
let computerScore = 0;

function getComputerChoice() {
  return choices[Math.floor(Math.random() * choices.length)];
}

function getResult(player, computer) {
  if (player === computer) return 'draw';
  if (
    (player === 'rock' && computer === 'scissors') ||
    (player === 'paper' && computer === 'rock') ||
    (player === 'scissors' && computer === 'paper')
  ) {
    return 'win';
  }
  return 'lose';
}

function updateScores() {
  playerScoreEl.textContent = playerScore;
  computerScoreEl.textContent = computerScore;
}

function playRound(playerChoice) {
  const computerChoice = getComputerChoice();
  const result = getResult(playerChoice, computerChoice);

  roundDisplay.textContent = `You ${icons[playerChoice]}  vs  ${icons[computerChoice]} Computer`;

  resultText.className = 'result-text';
  if (result === 'win') {
    playerScore++;
    resultText.textContent = 'You win this round!';
    resultText.classList.add('win');
  } else if (result === 'lose') {
    computerScore++;
    resultText.textContent = 'Computer wins this round!';
    resultText.classList.add('lose');
  } else {
    resultText.textContent = "It's a draw!";
    resultText.classList.add('draw');
  }

  updateScores();
}

function resetGame() {
  playerScore = 0;
  computerScore = 0;
  updateScores();
  roundDisplay.textContent = 'Make your move!';
  resultText.textContent = '';
  resultText.className = 'result-text';
}

choiceButtons.forEach((btn) => {
  btn.addEventListener('click', () => {
    playRound(btn.dataset.choice);
  });
});

resetBtn.addEventListener('click', resetGame);

updateScores();
